def sparkle(size=50):
 return f'<svg width="{size}" height="{size}" viewBox="0 0 100 100" fill="none"><path d="M50 4 Q54 43 96 50 Q55 55 50 96 Q45 55 4 50 Q44 45 50 4Z" fill="currentColor"/></svg>'
def tick():return '<svg viewBox="0 0 24 24" width="27" height="27" fill="none"><path d="m5 12 4 4 10-10" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>'
def chip(label='GPU',size=150):
 pins=''.join(f'<path d="M{v} 10v15 M{v} 125v15 M10 {v}h15 M125 {v}h15"/>' for v in [45,65,85,105])
 return f'<svg width="{size}" height="{size}" viewBox="0 0 150 150" fill="none"><g stroke="currentColor" stroke-width="2.3">{pins}<rect x="25" y="25" width="100" height="100" rx="16"/><rect x="38" y="38" width="74" height="74" rx="6"/></g><text x="75" y="85" text-anchor="middle" fill="currentColor" font-family="Arial" font-size="27" font-weight="700">{label}</text></svg>'
