# Sidecar captions and readable narration.
def stamp(t,sep=','):
 ms=round(t*1000);h,ms=divmod(ms,3600000);m,ms=divmod(ms,60000);s,ms=divmod(ms,1000);return f'{h:02d}:{m:02d}:{s:02d}{sep}{ms:03d}'
srt=[];vtt=['WEBVTT\n'];script=['# Motion, corrected.\n\nThree-minute narration, 379 words. No voiceover has been generated.\n']
for i,(a,b,t) in enumerate(cues):
 lines='\n'.join(textwrap.wrap(t,width=71,break_long_words=False,break_on_hyphens=False))
 srt.append(f'{i+1}\n{stamp(a)} --> {stamp(b)}\n{lines}\n')
 vtt.append(f'{stamp(a,".")} --> {stamp(b,".")}\n{lines}\n')
for s in story['scenes']:
 script.append(f'\n## {stamp(s["start"],".")[:8]}–{stamp(s["end"],".")[:8]} · {s["title"]}\n\n'+' '.join(c[2] for c in s['cues'])+'\n')
(R/'subtitles.srt').write_text('\n'.join(srt));(R/'subtitles.vtt').write_text('\n'.join(vtt));(R/'narration.md').write_text(''.join(script))
print('Built',R/'index.html', 'size', (R/'index.html').stat().st_size)
